func IdEventArrayToPQ(ids []IdEvent) pq.Int64Array {
	out := make(pq.Int64Array, len(ids))
	for i, v := range ids {
		out[i] = int64(v)
	}
	return out
}

// ScanIdEventArray scans the result of a query returning a
// list of ID's.
func ScanIdEventArray(rs *sql.Rows) ([]IdEvent, error) {
	defer rs.Close()
	ints := make([]IdEvent, 0, 16)
	var err error
	for rs.Next() {
		var s IdEvent
		if err = rs.Scan(&s); err != nil {
			return nil, err
		}
		ints = append(ints, s)
	}
	if err = rs.Err(); err != nil {
		return nil, err
	}
	return ints, nil
}

func SwitchValidationAndMessageDossier(db DB, to dossiers.IdDossier, from dossiers.IdDossier) error {
	_, err := db.Exec("UPDATE events SET IdDossier = $1 WHERE IdDossier = $2 AND (Kind = 2 /* EventKind.Message */ OR Kind = 1 /* EventKind.Statuation */);", to, from)
	return err
}
